contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 initialBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;
        bool reverted = false;

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(initialBal == 0 ? reverted || balBefore == 0 : reverted || balBefore == 0);
    }
}

